use verus::prelude::*;

verus! {

    /// Given a non‐empty vector `list` of 32‐bit integers and a 1‐based index `k`
    /// with 1 <= k < list.len(), return a new vector which is `list` with
    /// the element at position `k` removed.  The order of the remaining
    /// elements is preserved.
    fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32>
        requires
            // we must have at least two elements (so removing one is valid)
            list.len() >= 2 &&
            // k is 1‐based, and strictly less than the length
            1 <= k && k < list.len(),
        ensures |res: Vec<i32>| {
            // length drops by exactly one
            res.len() == list.len() - 1
            // prefix up to (k−1) in 1‐based, i.e. indices 0..(k-2) in 0‐based
            && forall |i: usize| i < k - 1 ==> res[i] == list[i]
            // suffix from (k+1) in 1‐based, i.e. indices k..(n-1) in 0‐based
            && forall |i: usize| i >= k - 1 && i < res.len() ==> res[i] == list[i + 1]
        }
    {
        // we'll build the result in this mutable vector
        let mut new_list: Vec<i32> = Vec::new();
        let mut i: usize = 0;

        // iterate over the original list, skipping exactly index k-1
        while i < list.len() {
            //--- LOOP INVARIANTS ------------------------------------------------
            // we never pass beyond the original length
            invariant i <= list.len();
            // the length of new_list is i when we haven't yet skipped,
            // and i-1 once we've skipped the k-1 element
            invariant
                new_list.len() ==
                if i <= k - 1 {
                    i
                } else {
                    i - 1
                };
            // content invariant: for all j < new_list.len(),
            // if j < k-1 then new_list[j] == list[j],
            // else new_list[j] == list[j+1].
            invariant forall |j: usize|
                j < new_list.len() ==>
                    if j < k - 1 {
                        new_list[j] == list[j]
                    } else {
                        new_list[j] == list[j + 1]
                    };
            // each iteration decreases the distance to the end
            decreases list.len() - i;
            //----------------------------------------------------------------------

            if i == k - 1 {
                // skip the k-1'th element
                i += 1;
            } else {
                // copy element i into new_list
                new_list.push(list[i]);
                i += 1;
            }
        }

        // at this point new_list.len() == list.len() - 1
        new_list
    }

}